    const centers = new Map();
    sectors.forEach((s, i) => {
      const col = i % cols;
      const row = Math.floor(i / cols);
      const x = x0 + (col + 0.5) * (gridW / cols);
      const y = y0 + (row + 0.5) * (gridH / rows);
      centers.set(s, { x, y });
