    if raw is None:
        return None
    s = str(raw).strip()
    if not s or s.lower() == 'nan':
        return None
    try:
        return float(s)
    except ValueError:
        return None


def load_min_stock_rows(csv_path: Path):
    with csv_path.open(newline='', encoding='utf-8') as f:
