import csv
import json
from pathlib import Path

OUT = Path('/root/output')


def parse_market_cap(raw: str | None):
    if raw is None:
        return None
    s = str(raw).strip()
    if not s or s.lower() == 'nan':
        return None
    try:
        return float(s)
    except ValueError:
        return None


def load_min_stock_rows(csv_path: Path):
    with csv_path.open(newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        rows = []
        for r in reader:
            ticker = (r.get('ticker') or '').strip()
            if not ticker:
                continue
            sector = (r.get('sector') or '').strip() or 'Unknown'
            full_name = (r.get('full name') or '').strip()
            market_cap = parse_market_cap(r.get('marketCap'))
            rows.append(
                {
                    'ticker': ticker,
                    'sector': sector,
                    'fullName': full_name,
                    'marketCap': market_cap,
                }
            )

    rows.sort(key=lambda x: (x['sector'], x['ticker']))
    return rows


def write_files():
    (OUT / 'js').mkdir(parents=True, exist_ok=True)
    (OUT / 'css').mkdir(parents=True, exist_ok=True)

    stocks = load_min_stock_rows(Path('/root/data/stock-descriptions.csv'))

    stocks_json = json.dumps(stocks, ensure_ascii=False, separators=(',', ':'))

