    svg.append('circle')
      .attr('cx', width / 2)
      .attr('cy', height / 2)
      .attr('r', 1.2)
      .attr('fill', 'rgba(232, 238, 252, 0.25)');

    // Save for selection updates.
    setSelectedTicker(state.selectedTicker ?? data[0]?.ticker);

