  --sans: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: var(--sans);
  background: radial-gradient(1200px 650px at 20% 0%, #13224a 0%, var(--bg) 58%, #070a14 100%);
  color: var(--text);
}

.header {
  padding: 18px 22px;
  border-bottom: 1px solid var(--stroke);
  background: linear-gradient(180deg, rgba(16,26,51,0.9) 0%, rgba(16,26,51,0.5) 100%);
  position: sticky;
  top: 0;
  z-index: 10;
  backdrop-filter: blur(8px);
}

.header__title {
  font-size: 18px;
  letter-spacing: 0.2px;
  font-weight: 650;
}

.header__subtitle {
  margin-top: 6px;
  font-size: 13px;
  color: var(--muted);
}

.app {
  display: flex;
  gap: 14px;
  padding: 14px;
  align-items: stretch;
}

.panel {
  background: linear-gradient(180deg, rgba(16,26,51,0.95) 0%, rgba(15,24,48,0.88) 100%);
  border: 1px solid var(--stroke);
  border-radius: 14px;
  box-shadow: var(--shadow);
  padding: 12px;
  min-height: calc(100vh - 90px);
}

#bubble-panel { flex: 1 1 56%; }
#table-panel  { flex: 1 1 44%; }

.panel__title {
  font-size: 13px;
  color: var(--muted);
  margin: 2px 0 10px 2px;
}

.chart {
  width: 100%;
  height: 560px;
  border: 1px solid var(--stroke);
  border-radius: 12px;
  background: radial-gradient(700px 520px at 50% 35%, rgba(122,162,255,0.10) 0%, rgba(0,0,0,0) 64%);
  overflow: hidden;
}

.legend {
  margin-top: 10px;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px 10px;
}

.legend__item {
  display: flex;
  gap: 8px;
  align-items: center;
  font-size: 12px;
  color: var(--muted);
}

.legend__swatch {
  width: 12px;
  height: 12px;
  border-radius: 3px;
  border: 1px solid rgba(255,255,255,0.18);
}

.table-container {
  width: 100%;
  height: calc(100% - 30px);
  border: 1px solid var(--stroke);
  border-radius: 12px;
  overflow: auto;
  background: rgba(0, 0, 0, 0.12);
}

.table {
  width: 100%;
  border-collapse: collapse;
}

.table thead th {
  position: sticky;
  top: 0;
  z-index: 2;
  text-align: left;
  font-size: 12px;
  padding: 10px 10px;
  color: var(--text);
  background: rgba(11, 16, 32, 0.92);
  border-bottom: 1px solid var(--stroke-strong);
}

.table tbody td {
  font-size: 12px;
  padding: 9px 10px;
  border-bottom: 1px solid rgba(232, 238, 252, 0.06);
  color: rgba(232, 238, 252, 0.92);
}

.table tbody tr {
  cursor: pointer;
}

.table tbody tr:hover {
  background: rgba(122, 162, 255, 0.12);
}

.table tbody tr.is-selected {
  background: rgba(255, 210, 122, 0.14);
  outline: 1px solid rgba(255, 210, 122, 0.38);
}

.ticker {
  font-family: var(--mono);
  letter-spacing: 0.3px;
}

.tooltip {
  position: absolute;
  left: 0;
  top: 0;
  transform: translate(-9999px, -9999px);
  padding: 10px 12px;
  border-radius: 10px;
  border: 1px solid rgba(255,255,255,0.14);
  background: rgba(7, 10, 20, 0.92);
  color: var(--text);
  box-shadow: 0 10px 30px rgba(0,0,0,0.45);
  pointer-events: none;
  opacity: 0;
  transition: opacity 140ms ease;
  max-width: 340px;
}

.tooltip.is-visible {
  opacity: 1;
}

.tooltip__ticker {
  font-family: var(--mono);
  color: var(--selected);
  font-weight: 650;
}

.tooltip__name {
  margin-top: 4px;
  font-size: 13px;
  line-height: 1.2;
}

.tooltip__sector {
  margin-top: 6px;
  font-size: 12px;
  color: var(--muted);
}

/* Bubble styling */
.node circle {
  stroke: rgba(255,255,255,0.18);
  stroke-width: 1;
}

.node.is-selected circle {
  stroke: rgba(255, 210, 122, 0.95);
  stroke-width: 2.5;
}

.node text {
  fill: rgba(232, 238, 252, 0.95);
  font-family: var(--mono);
  pointer-events: none;
  text-anchor: middle;
  dominant-baseline: middle;
}

@media (max-width: 1050px) {
  .app {
    flex-direction: column;
  }
  .panel {
    min-height: auto;
  }
  .chart {
    height: 520px;
  }
  .legend {
    grid-template-columns: 1fr;
  }
}
""".lstrip()

