    moveTooltip(event);
  }

  function hideTooltip() {
    setTooltipVisible(false);
  }

  function setSelectedTicker(ticker) {
    state.selectedTicker = ticker;

    d3.selectAll('.node')
      .classed('is-selected', d => d.ticker === ticker);

    d3.selectAll('tr[data-ticker]')
