      .data(sectors, d => d);

    const enter = items.enter()
      .append('div')
      .attr('class', 'legend__item');

    enter.append('div')
      .attr('class', 'legend__swatch')
      .style('background', d => color(d));

    enter.append('div')
      .attr('class', 'legend__label')
      .text(d => d);

    items.exit().remove();
